"""Version 2026.2 lesson expansions for the A2–B2 mission courses.

The added material is original Parlez practice content. It broadens coverage and
retrieval opportunities, but does not constitute qualified pedagogical review.
"""

from __future__ import annotations

from .types import DialogueLine, Exercise, GrammarExample, GrammarRule, Lesson, VocabItem


def _mc(prompt, options, answer, explanation):
    return {"type": "multiple_choice", "prompt": prompt, "options": options, "answer": answer, "explanation": explanation}


def _fill(prompt, answer, explanation, acceptable=None):
    return {
        "type": "fill_blank",
        "prompt": prompt,
        "answer": answer,
        "acceptable": acceptable or [],
        "explanation": explanation,
    }


def _translate(prompt, answer, explanation, acceptable=None):
    return {
        "type": "translate_to_fr",
        "prompt": prompt,
        "answer": answer,
        "acceptable": acceptable or [],
        "explanation": explanation,
    }


def _dictation(prompt, text, explanation):
    return {
        "type": "dictation",
        "prompt": prompt,
        "audioText": text,
        "answer": text,
        "explanation": explanation,
    }


def _lesson(
    lesson_id,
    title,
    title_fr,
    description,
    objectives,
    skill_tags,
    transfer_task,
    vocabulary,
    grammar_title,
    grammar_explanation,
    grammar_examples,
    dialogue,
    exercise_specs,
    self_check,
    *,
    minutes=30,
    cultural_note=None,
):
    return Lesson(
        id=lesson_id,
        title=title,
        titleFr=title_fr,
        description=description,
        objectives=objectives,
        skillTags=skill_tags,
        transferTask=transfer_task,
        selfCheck=self_check,
        vocabulary=[VocabItem(fr=fr, en=en, category=category, example=example, exampleEn=example_en)
                    for fr, en, category, example, example_en in vocabulary],
        grammar=[GrammarRule(
            title=grammar_title,
            explanation=grammar_explanation,
            examples=[GrammarExample(fr=fr, en=en) for fr, en in grammar_examples],
        )],
        dialogue=[DialogueLine(speaker=speaker, name=name, fr=fr, en=en)
                  for speaker, name, fr, en in dialogue],
        exercises=[Exercise(id=f"{lesson_id}-e{index}", **spec)
                   for index, spec in enumerate(exercise_specs, start=1)],
        culturalNote=cultural_note,
        estimatedMinutes=minutes,
    )


