            [("J'ai passé commande le 4 mai et le suivi n'a pas changé depuis lundi.", "I placed the order on May 4 and the tracking has not changed since Monday."),
             ("Pourriez-vous vérifier le dossier et m'indiquer le délai prévu ?", "Could you check the file and tell me the expected timeframe?")],
