def expand_mission_courses(courses):
    """Append one richer lesson to every A2–B2 unit and bump the content version."""
    for level, course in courses.items():
        if level not in {"A2", "B1", "B2"}:
            continue
        by_id = {unit.id: unit for unit in course.units}
        for unit_id, lessons in _EXPANDED_LESSONS.items():
            if unit_id not in by_id:
                continue
            unit = by_id[unit_id]
            if not any(existing.id == lessons[0].id for existing in unit.lessons):
                unit.lessons.extend(lessons)
            outcome, criterion = _UNIT_REVISIONS[unit_id]
            if outcome not in unit.outcomes:
                unit.outcomes.append(outcome)
            if criterion not in unit.capstoneCriteria:
                unit.capstoneCriteria.append(criterion)
        course.version = "2026.2"
        course.description = course.description.replace(
            "Each module ends with a useful task; closed exercises are practice, not a proficiency test.",
            "Each module includes sequenced lessons and a useful transfer task; closed exercises are practice, not a proficiency test.",
        )
        course.contentStatus = "published_unattested"
        expansion_note = (
            "Version 2026.2 contains 24 original practice lessons (three per unit). This is not official CEFR/NCLC certification or an official test result."
        )
        if expansion_note not in course.description:
            course.description = f"{course.description.rstrip()} {expansion_note}"
        revision_outcome = {
            "A2": "Adapt short accounts, requests, and plans when familiar circumstances change.",
            "B1": "Summarize short sources, support practical proposals, and check that shared information is understood.",
            "B2": "Synthesize attributed evidence, mediate disagreement, and qualify recommendations for an audience.",
        }[level]
        if revision_outcome not in course.levelOutcomes:
            course.levelOutcomes.append(revision_outcome)


__all__ = ["expand_mission_courses"]
